"use strict";document.addEventListener("DOMContentLoaded",function(){var magicelements=["rc-cart-count"];for(var i=0;i<magicelements.length;i++){var cls=magicelements[i];var val=localStorage.getItem(cls);var elements=document.getElementsByClassName(cls);for(var i=0;i<elements.length;i++){elements[i].textContent=val;elements[i].removeAttribute("hidden")}}})